    const _FSL = '/'.charCodeAt(0);
    const _NWL = '\n'.charCodeAt(0);
    const _CAR = '\r'.charCodeAt(0);
    const _LFD = '\f'.charCodeAt(0);
    const _TIC = '`'.charCodeAt(0);
    const _DOT = '.'.charCodeAt(0);
